 }
}

sources.DeferredExpiry.ts:
export class DeferredExpiry {
 private records: Map<string,Entry> = new Map()
 schedule(limit: number): void {
  queueMicrotask(() => {
   if (this.records.size > limit) {
    for (const [key,record] of this.records) {
     if (record.updatedAt < 100) { this.records.delete(key) }
    }
   }
  })
 }
}

